{"path": "zipper.py", "content": "class Zipper:
    """Zipper over binary trees of the form {"value": v, "left": t|None, "right": t|None}."""

    def __init__(self, tree, path):
        self._tree = tree
        self._path = path  # list of (direction, parent_value, other_subtree)

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self._tree["value"]

    def set_value(self, value):
        return Zipper(dict(self._tree, value=value), self._path)

    def left(self):
        if self._tree["left"] is None:
            return None
        return Zipper(self._tree["left"],
                      self._path + [("left", self._tree["value"], self._tree["right"])])

    def set_left(self, tree):
        return Zipper(dict(self._tree, left=tree), self._path)

    def right(self):
        if self._tree["right"] is None:
            return None
        return Zipper(self._tree["right"],
                      self._path + [("right", self._tree["value"], self._tree["left"])])

    def set_right(self, tree):
        return Zipper(dict(self._tree, right=tree), self._path)

    def up(self):
        if not self._path:
            return None
        direction, value, other = self._path[-1]
        if direction == "left":
            parent = {"value": value, "left": self._tree, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._tree}
        return Zipper(parent, self._path[:-1])

    def to_tree(self):
        z = self
        while z._path:
            z = z.up()
        return z._tree

    def __eq__(self, other):
        return (isinstance(other, Zipper) and self._tree == other._tree
                and self._path == other._path)
